                    /* Without -a, consolidate: do nothing until child exits */
                } else {
                    run_utility(triggered_path);

                    if (!opt_restart) {
                        status = wait_for_child();

                        if (opt_status && awk_pipe) {
                            report_status(0, status);
                        }

                        if (opt_exit) {
                            if (awk_pipe) {
                                fclose(awk_pipe);
                                awk_pipe = NULL;
                                if (awk_pid > 0) {
                                    waitpid(awk_pid, NULL, 0);
                                    awk_pid = 0;
                                }
                            }
                            return get_entr_exit_code(status);
                        }
                    }
                }
            }
        }

        /* Check TTY input */
        if (!opt_noninteractive && nfds > 1 && (fds[1].revents & POLLIN)) {
            char c;
            if (read(tty_fd, &c, 1) == 1) {
                if (c == 'q' || c == 3) {  /* 'q' or Ctrl-C */
                    break;
                } else if (c == ' ') {
                    if (opt_restart) {
                        kill_child();
                        run_utility(triggered_path);
                    } else if (!child_running) {
                        run_utility(triggered_path);
                        status = wait_for_child();

                        if (opt_status && awk_pipe) {
                            report_status(0, status);
                        }

                        if (opt_exit) {
                            if (awk_pipe) {
                                fclose(awk_pipe);
                                awk_pipe = NULL;
                                if (awk_pid > 0) {
                                    waitpid(awk_pid, NULL, 0);
                                    awk_pid = 0;
                                }
                            }
                            return get_entr_exit_code(status);
                        }
                    }
                }
            }
        }
    }

    /* Cleanup */
    if (child_running && child_pid > 0) {
        kill(child_pid, SIGTERM);
        waitpid(child_pid, NULL, 0);
    }

    if (awk_pipe) {
        fclose(awk_pipe);
        if (awk_pid > 0) waitpid(awk_pid, NULL, 0);
    }

    return 0;
}
