        }
        perror("awk");
        exit(1);
    }

    /* Parent: write to awk via pipe */
    close(pipefd[0]);
    awk_pipe = fdopen(pipefd[1], "w");
    if (!awk_pipe) {
        perror("fdopen");
        close(pipefd[1]);
