    const char *trig = (trigger_path && trigger_path[0]) ? trigger_path : first_file;

    argv = malloc((utility_argc + 2) * sizeof(char *));
    if (!argv) return NULL;

    for (i = 0; i < utility_argc; i++) {
        if (strcmp(utility_argv[i], "/_") == 0) {
            argv[i] = strdup(trig);
        } else {
            argv[i] = utility_argv[i];
        }
    }
    argv[utility_argc] = NULL;

    if (argc_out) *argc_out = utility_argc;
