{
    if (opt_clear >= 2) {
        /* Clear screen and erase scrollback buffer */
        write(STDOUT_FILENO, "\033[2J\033[3J\033[H", 10);
    } else if (opt_clear >= 1) {
        /* Just clear screen and go to home position */
        write(STDOUT_FILENO, "\033[2J\033[H", 7);
    }
}

static int
parse_restart_signal(const char *signame)
{
    const char *name = signame;

    /* Strip "SIG" prefix */
    if (strncmp(name, "SIG", 3) == 0) {
        name += 3;
    }

    if (strcmp(name, "HUP") == 0)  return SIGHUP;
    if (strcmp(name, "INT") == 0)  return SIGINT;
    if (strcmp(name, "QUIT") == 0) return SIGQUIT;
    if (strcmp(name, "TERM") == 0) return SIGTERM;
    if (strcmp(name, "USR1") == 0) return SIGUSR1;
    if (strcmp(name, "USR2") == 0) return SIGUSR2;

    return -1;
}

static int
setup_awk(void)
{
    const char *script_path;
    char default_path[PATH_MAX_LEN];
    const char *home;
    FILE *fp;

    /* Get status script path */
    script_path = getenv("ENTR_STATUS_SCRIPT");
    if (!script_path || script_path[0] == '\0') {
        home = getenv("HOME");
        if (!home) home = "/root";
        snprintf(default_path, sizeof(default_path), "%s/.entr/status.awk", home);
        script_path = default_path;
    }

    strncpy(status_script, script_path, sizeof(status_script) - 1);

    /* Create default script if it doesn't exist */
    if (access(script_path, F_OK) != 0) {
        char dir[PATH_MAX_LEN];
        strncpy(dir, script_path, sizeof(dir) - 1);
        char *d = dirname(dir);

        /* Create directory */
        if (mkdir(d, 0755) != 0 && errno != EEXIST) {
            fprintf(stderr, "%s: unable to create '%s'\n", progname, d);
            return -1;
