cat > /workspace/entr.c << 'ENTR_C'
/*
 * entr - Event Notify Test Runner
 * Version 5.7
 *
 * Reimplementation of entr utility for watching files and running commands
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <sys/inotify.h>
#include <poll.h>
#include <limits.h>
#include <termios.h>
#include <libgen.h>

#define ENTR_VERSION "5.7"
#define MAX_FILES 4096
#define PATH_MAX_LEN PATH_MAX
#define INOTIFY_BUF_LEN (10 * (sizeof(struct inotify_event) + NAME_MAX + 1))

/* Inotify event flags for file watching */
#define FILE_WATCH_MASK (IN_CLOSE_WRITE | IN_MOVE_SELF | IN_ATTRIB | IN_DELETE_SELF | IN_MODIFY)
#define DIR_WATCH_MASK  (IN_CREATE | IN_MOVED_TO | IN_DELETE)

/* Options */
static int opt_all = 0;            /* -a: respond to all events */
static int opt_clear = 0;          /* -c: clear screen (count) */
static int opt_dir = 0;            /* -d: track directories (count) */
static int opt_noninteractive = 0; /* -n: non-interactive mode */
static int opt_postpone = 0;       /* -p: postpone first execution */
static int opt_restart = 0;        /* -r: restart persistent process */
static int opt_shell = 0;          /* -s: use shell */
static int opt_status = 0;         /* -x: format exit status (count) */
static int opt_exit = 0;           /* -z: exit after utility completes */

/* Program name for error messages */
static const char *progname = "entr";

/* File watch structure */
typedef struct {
    char path[PATH_MAX_LEN];
    int wd;             /* inotify watch descriptor */
    struct stat st;     /* last known stat */
} WatchFile;

static WatchFile watched[MAX_FILES];
static int num_watched = 0;

/* Directory watch structure */
typedef struct {
    char path[PATH_MAX_LEN];
    int wd;
} DirWatch;

static DirWatch dir_watches[MAX_FILES];
static int num_dir_watches = 0;

/* Inotify fd */
static int inotify_fd = -1;

/* TTY fd */
static int tty_fd = -1;
static struct termios saved_tty;

/* Child process state */
static pid_t child_pid = 0;
static int child_running = 0;
static int pending_run = 0;        /* Set when an event arrives while child is running */
static char triggered_path[PATH_MAX_LEN] = "";

/* Signal flags */
static volatile sig_atomic_t sigchld_received = 0;
static volatile sig_atomic_t sigint_received = 0;

/* Restart signal (default SIGTERM) */
static int restart_signal = SIGTERM;

/* Utility command */
static char **utility_argv = NULL;
static int utility_argc = 0;

/* AWK process for -x flag */
static FILE *awk_pipe = NULL;
static pid_t awk_pid = 0;

/* Status script path */
static char status_script[PATH_MAX_LEN] = "";

/* Last child exit status */
static int last_exit_status = 0;
static pid_t last_child_pid = 0;

static void
usage(void)
{
    fprintf(stderr, "release: %s\n", ENTR_VERSION);
    fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
    fprintf(stderr, "hint: use -h to display option summary\n");
}

static void
usage_full(void)
{
    fprintf(stderr, "release: %s\n", ENTR_VERSION);
    fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
    fprintf(stderr, "summary:\n");
    fprintf(stderr, "    -a  Do not consolidate events\n");
    fprintf(stderr, "    -c  Clear screen before execution\n");
    fprintf(stderr, "    -d  Track files added or removed from directories\n");
    fprintf(stderr, "    -n  Non-interactive mode\n");
    fprintf(stderr, "    -p  Wait for first event\n");
    fprintf(stderr, "    -r  Run as a background process, use signal to restart\n");
    fprintf(stderr, "    -s  Evaluate using a shell\n");
    fprintf(stderr, "    -x  Format exit status\n");
    fprintf(stderr, "    -z  Exit after the utility completes\n");
    fprintf(stderr, "docs:\n");
    fprintf(stderr, "    man entr\n");
}

static void
handle_sigchld(int sig)
{
    (void)sig;
    sigchld_received = 1;
}

static void
handle_sigint(int sig)
{
    (void)sig;
    sigint_received = 1;
}

static void
restore_tty(void)
{
    if (tty_fd >= 0) {
        tcsetattr(tty_fd, TCSANOW, &saved_tty);
    }
}

static int
open_tty(void)
{
    struct termios tty;

    tty_fd = open("/dev/tty", O_RDONLY | O_CLOEXEC);
    if (tty_fd < 0) {
        fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", progname);
        return -1;
    }

    if (tcgetattr(tty_fd, &saved_tty) < 0) {
        fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", progname);
        close(tty_fd);
        tty_fd = -1;
        return -1;
    }

    tty = saved_tty;
    tty.c_lflag &= ~(ICANON | ECHO);
    tty.c_cc[VMIN] = 1;
    tty.c_cc[VTIME] = 0;
    tcsetattr(tty_fd, TCSANOW, &tty);
    atexit(restore_tty);
    return 0;
}

static void
clear_screen(void)
{
    if (opt_clear >= 2) {
        /* Clear screen and erase scrollback buffer: ESC[2J ESC[3J ESC[H */
        if (write(STDOUT_FILENO, "\033[2J\033[3J\033[H", 11) < 0) { /* ignore */ }
    } else if (opt_clear >= 1) {
        /* Just clear screen and go to home position: ESC[2J ESC[H */
        if (write(STDOUT_FILENO, "\033[2J\033[H", 7) < 0) { /* ignore */ }
    }
}

static int
parse_restart_signal(const char *signame)
{
    const char *name = signame;

    /* Strip "SIG" prefix */
    if (strncmp(name, "SIG", 3) == 0) {
        name += 3;
    }

    /* Only HUP, INT, QUIT are recognized (matching original binary behavior) */
    if (strcmp(name, "HUP") == 0)  return SIGHUP;
    if (strcmp(name, "INT") == 0)  return SIGINT;
    if (strcmp(name, "QUIT") == 0) return SIGQUIT;

    return -1;
}

static int
setup_awk(void)
{
    const char *script_path;
    char default_path[PATH_MAX_LEN];
    const char *home;
    FILE *fp;

    /* Get status script path */
    script_path = getenv("ENTR_STATUS_SCRIPT");
    if (!script_path || script_path[0] == '\0') {
        home = getenv("HOME");
        if (!home) home = "/root";
        snprintf(default_path, sizeof(default_path), "%s/.entr/status.awk", home);
        script_path = default_path;
    }

    strncpy(status_script, script_path, sizeof(status_script) - 1);
    status_script[sizeof(status_script) - 1] = '\0';

    /* Create default script if it doesn't exist */
    if (access(script_path, F_OK) != 0) {
        char dir[PATH_MAX_LEN];
        char dir2[PATH_MAX_LEN];
        strncpy(dir, script_path, sizeof(dir) - 1);
        dir[sizeof(dir) - 1] = '\0';
        strncpy(dir2, dir, sizeof(dir2) - 1);
        char *d = dirname(dir2);

        /* Create directory */
        if (mkdir(d, 0755) != 0 && errno != EEXIST) {
            fprintf(stderr, "%s: unable to create '%s'\n", progname, d);
            return -1;
        }

        fp = fopen(script_path, "w");
        if (!fp) {
            fprintf(stderr, "%s: unable to create '%s'\n", progname, script_path);
            return -1;
        }
        fprintf(fp, "# http://eradman.com/entrproject/status-filters.html\n");
        fprintf(fp, "/^signal/ { print $3, \"terminated by signal\", $2; }\n");
        fprintf(fp, "/^exit/ { print $3, \"returned exit code\", $2; }\n");
        fclose(fp);
        fprintf(stderr, "entr: created '%s'\n", script_path);
    }

    return 0;
}

static void
start_awk(void)
{
    int pipefd[2];

    if (pipe(pipefd) < 0) {
        perror("pipe");
        return;
    }

    awk_pid = fork();
    if (awk_pid < 0) {
        perror("fork");
        close(pipefd[0]);
        close(pipefd[1]);
        return;
    }

    if (awk_pid == 0) {
        /* Child: run awk */
        close(pipefd[1]);
        if (dup2(pipefd[0], STDIN_FILENO) < 0) exit(1);
        close(pipefd[0]);

        if (opt_status >= 2) {
            /* Full mode: awk without sandbox */
            execlp("awk", "awk", "-F|", "-f", status_script, NULL);
        } else {
            /* Sandbox mode: awk with -S (gawk only) */
            execlp("awk", "awk", "-S", "-F|", "-f", status_script, NULL);
        }
        perror("awk");
        exit(1);
    }

    /* Parent: write to awk via pipe */
    close(pipefd[0]);
    awk_pipe = fdopen(pipefd[1], "w");
    if (!awk_pipe) {
        perror("fdopen");
        close(pipefd[1]);
    }
}

static const char *
get_cmdname(void)
{
    const char *cmd;
    if (opt_shell) {
        const char *shell = getenv("SHELL");
        if (!shell || shell[0] == '\0') shell = "/bin/sh";
        cmd = strrchr(shell, '/');
        return cmd ? cmd + 1 : shell;
    }
    cmd = utility_argv[0];
    const char *base = strrchr(cmd, '/');
    return base ? base + 1 : cmd;
}

static void
report_status(int status)
{
    if (!awk_pipe) return;

    if (WIFEXITED(status)) {
        int exit_code = WEXITSTATUS(status);
        fprintf(awk_pipe, "exit|%d|%s\n", exit_code, get_cmdname());
        fflush(awk_pipe);
    } else if (WIFSIGNALED(status)) {
        int sig_num = WTERMSIG(status);
        fprintf(awk_pipe, "signal|%d|%s\n", sig_num, get_cmdname());
        fflush(awk_pipe);
    }
}

static int
get_entr_exit_code(int status)
{
    if (WIFEXITED(status)) {
        return WEXITSTATUS(status);
    } else if (WIFSIGNALED(status)) {
        return 128 + WTERMSIG(status);
    }
    return 1;
}

static void
cleanup_awk(void)
{
    if (awk_pipe) {
        fclose(awk_pipe);
        awk_pipe = NULL;
    }
    if (awk_pid > 0) {
        waitpid(awk_pid, NULL, 0);
        awk_pid = 0;
    }
}

static void
kill_child(void)
{
    if (child_pid > 0) {
        /* Kill the entire process group */
        if (kill(-child_pid, restart_signal) < 0) {
            kill(child_pid, restart_signal);
        }
        /* Wait for it to die */
        int ws;
        waitpid(child_pid, &ws, 0);
        child_pid = 0;
        child_running = 0;
    }
}

/* Check for child exit (non-blocking) */
static int
check_child_exit(void)
{
    if (child_pid <= 0) return 0;

    int ws;
    pid_t pid = waitpid(child_pid, &ws, WNOHANG);
    if (pid <= 0) return 0;

    last_exit_status = ws;
    last_child_pid = pid;
    child_pid = 0;
    child_running = 0;
    return 1;
}

/* Blocking wait for child */
static int
wait_child(void)
{
    if (child_pid <= 0) return 0;

    int ws;
    pid_t pid = waitpid(child_pid, &ws, 0);
    if (pid <= 0) return 0;

    last_exit_status = ws;
    last_child_pid = pid;
    child_pid = 0;
    child_running = 0;
    return 1;
}

static void
run_utility(const char *trigger_path)
{
    const char *shell;
    const char *first_file;

    if (opt_clear) {
        clear_screen();
    }

    first_file = (num_watched > 0) ? watched[0].path : "";
    const char *trig = (trigger_path && trigger_path[0]) ? trigger_path : first_file;

    child_pid = fork();
    if (child_pid < 0) {
        perror("fork");
        return;
    }

    if (child_pid == 0) {
        /* Child process */
        if (opt_restart) {
            /* Create a new process group for this child */
            if (setpgid(0, 0) < 0) {
                /* ignore */
            }
        }

        /* Set PAGER if not set */
        if (!getenv("PAGER") || getenv("PAGER")[0] == '\0') {
            setenv("PAGER", "/bin/cat", 1);
        }

        if (opt_shell) {
            shell = getenv("SHELL");
            if (!shell || shell[0] == '\0') shell = "/bin/sh";
            execl(shell, shell, "-c", utility_argv[0], trig, NULL);
            perror("exec");
            exit(1);
        } else {
            /* Build exec argv with /_ replacement */
            char **exec_argv = malloc((utility_argc + 2) * sizeof(char *));
            if (!exec_argv) exit(1);

            for (int i = 0; i < utility_argc; i++) {
                if (strcmp(utility_argv[i], "/_") == 0) {
                    exec_argv[i] = (char *)trig;
                } else {
                    exec_argv[i] = utility_argv[i];
                }
            }
            exec_argv[utility_argc] = NULL;

            execvp(exec_argv[0], exec_argv);
            perror("exec");
            exit(1);
        }
    }

    /* Parent */
    if (opt_restart) {
        /* Set process group for child */
        setpgid(child_pid, child_pid);
    }

    child_running = 1;
}

static void
add_dir_watch(int ifd, const char *path)
{
    int i;
    int wd;

    /* Check if already watching this directory */
    for (i = 0; i < num_dir_watches; i++) {
        if (strcmp(dir_watches[i].path, path) == 0) {
            return;
        }
    }

    if (num_dir_watches >= MAX_FILES) return;

    wd = inotify_add_watch(ifd, path, DIR_WATCH_MASK);
    if (wd < 0) return;

    strncpy(dir_watches[num_dir_watches].path, path, PATH_MAX_LEN - 1);
    dir_watches[num_dir_watches].path[PATH_MAX_LEN - 1] = '\0';
    dir_watches[num_dir_watches].wd = wd;
    num_dir_watches++;
}

static int
load_files(void)
{
    char line[PATH_MAX_LEN];
    struct stat st;

    while (fgets(line, sizeof(line), stdin) != NULL) {
        int len = strlen(line);

        /* Remove trailing newline */
        if (len > 0 && line[len-1] == '\n') {
            line[--len] = '\0';
        }

        /* Skip empty lines */
        if (len == 0) continue;

        /* Skip if too many files */
        if (num_watched >= MAX_FILES) {
            fprintf(stderr, "%s: too many files\n", progname);
            break;
        }

        /* Stat the file */
        if (stat(line, &st) != 0) {
            fprintf(stderr, "%s: unable to stat '%s'\n", progname, line);
            continue;
        }

        strncpy(watched[num_watched].path, line, PATH_MAX_LEN - 1);
        watched[num_watched].path[PATH_MAX_LEN - 1] = '\0';
        watched[num_watched].st = st;
        watched[num_watched].wd = -1;
        num_watched++;
    }

    return num_watched;
}

static void
setup_watches(int ifd)
{
    int i;
    int wd;
    char dir_buf[PATH_MAX_LEN];

    for (i = 0; i < num_watched; i++) {
        wd = inotify_add_watch(ifd, watched[i].path, FILE_WATCH_MASK);
        if (wd < 0) {
            fprintf(stderr, "%s: cannot open '%s': %s\n",
                    progname, watched[i].path, strerror(errno));
            continue;
        }
        watched[i].wd = wd;
    }

    if (opt_dir) {
        /* Also watch parent directories */
        for (i = 0; i < num_watched; i++) {
            strncpy(dir_buf, watched[i].path, sizeof(dir_buf) - 1);
            dir_buf[sizeof(dir_buf) - 1] = '\0';
            char dir_buf2[PATH_MAX_LEN];
            strncpy(dir_buf2, dir_buf, sizeof(dir_buf2) - 1);
            char *dir_path = dirname(dir_buf2);
            add_dir_watch(ifd, dir_path);
        }
    }
}

static int
find_watched_by_wd(int wd)
{
    int i;
    for (i = 0; i < num_watched; i++) {
        if (watched[i].wd == wd) return i;
    }
    return -1;
}

static int
find_dir_by_wd(int wd)
{
    int i;
    for (i = 0; i < num_dir_watches; i++) {
        if (dir_watches[i].wd == wd) return i;
    }
    return -1;
}

static void
ev_trace_print(int idx, const char *path, unsigned int fflags, const struct stat *st)
{
    fprintf(stderr, "%d/%d: fflags: 0x%x r %o %s\n",
            idx, num_watched + num_dir_watches,
            fflags, st->st_mode, path);
}

/* 
 * Process pending inotify events.
 * Returns:
 *  0 = no triggering events
 *  1 = file event (triggering)
 *  2 = directory change (need to exit with code 2)
 * out_trigger is set to the triggering file path.
 */
static int
drain_inotify(int ifd, char *out_trigger, int out_size, int ev_trace)
{
    char buf[INOTIFY_BUF_LEN];
    ssize_t len;
    struct inotify_event *event;
    int triggered = 0;
    int dir_changed = 0;

    len = read(ifd, buf, sizeof(buf));
    if (len < 0) {
        if (errno == EINTR || errno == EAGAIN) return 0;
        return -1;
    }

    for (char *p = buf; p < buf + len; ) {
        event = (struct inotify_event *)p;
        p += sizeof(struct inotify_event) + event->len;

        /* Check if this is a file event */
        int idx = find_watched_by_wd(event->wd);
        if (idx >= 0) {
            unsigned int fflags = event->mask;
            struct stat *st = &watched[idx].st;

            /* Re-stat to get updated info */
            struct stat new_st;
            if (stat(watched[idx].path, &new_st) == 0) {
                *st = new_st;
            }

            if (ev_trace) {
                ev_trace_print(idx, watched[idx].path, fflags, st);
            }

            /* File was deleted or moved - re-add watch */
            if (fflags & (IN_DELETE_SELF | IN_MOVE_SELF)) {
                inotify_rm_watch(ifd, watched[idx].wd);
                watched[idx].wd = inotify_add_watch(ifd, watched[idx].path, FILE_WATCH_MASK);
            }

            if (out_trigger && !triggered) {
                strncpy(out_trigger, watched[idx].path, out_size - 1);
                out_trigger[out_size - 1] = '\0';
            }
            triggered = 1;
        }

        /* Check if this is a directory event */
        int dir_idx = find_dir_by_wd(event->wd);
        if (dir_idx >= 0 && (event->mask & (IN_CREATE | IN_MOVED_TO))) {
            if (event->len > 0) {
                const char *name = event->name;
                /* With -dd, all files; with -d, skip hidden files */
                if (opt_dir >= 2 || name[0] != '.') {
                    dir_changed = 1;
                    if (out_trigger && !triggered) {
                        snprintf(out_trigger, out_size, "%s/%s",
                                dir_watches[dir_idx].path, name);
                    }
                    triggered = 1;
                }
            }
        }

        /* Check for directory deletion */
        if (dir_idx >= 0 && (event->mask & IN_DELETE)) {
            if (event->len > 0) {
                dir_changed = 1;
            }
        }
    }

    if (dir_changed) return 2;
    return triggered ? 1 : 0;
}

/* 
 * Drain all pending inotify events without acting on them.
 * Used to consolidate events while child is running.
 */
static void
drain_inotify_silent(int ifd)
{
    char buf[INOTIFY_BUF_LEN];
    struct pollfd pfd;
    pfd.fd = ifd;
    pfd.events = POLLIN;

    while (1) {
        if (poll(&pfd, 1, 0) <= 0) break;
        if (!(pfd.revents & POLLIN)) break;
        ssize_t n = read(ifd, buf, sizeof(buf));
        if (n <= 0) break;
    }
}

int
main(int argc, char *argv[])
{
    int ch;
    int ev_trace = 0;
    int ifd;
    struct pollfd fds[2];
    int nfds;
    int exit_code = 0;
    int inotify_workaround = 0;
    char trigger_path[PATH_MAX_LEN] = "";

    /* Set program name */
    if (argc > 0) {
        const char *p = strrchr(argv[0], '/');
        progname = p ? p + 1 : argv[0];
    }

    /* Parse options ('+' prefix for POSIX-correct parsing) */
    while ((ch = getopt(argc, argv, "+acdnprsxzh")) != -1) {
        switch (ch) {
        case 'a': opt_all = 1; break;
        case 'c': opt_clear++; break;
        case 'd': opt_dir++; break;
        case 'n': opt_noninteractive = 1; break;
        case 'p': opt_postpone = 1; break;
        case 'r': opt_restart = 1; break;
        case 's': opt_shell = 1; break;
        case 'x': opt_status++; break;
        case 'z': opt_exit = 1; break;
        case 'h':
            usage_full();
            return 1;
        default:
            usage();
            return 1;
        }
    }

    argc -= optind;
    argv += optind;

    if (argc < 1) {
        usage();
        return 1;
    }

    /* Check for incompatible options */
    if (opt_restart && opt_status) {
        fprintf(stderr, "%s: -r and -x may not be combined\n", progname);
        return 1;
    }

    if (opt_shell && argc > 1) {
        fprintf(stderr, "%s: -s requires commands to be formatted as a single argument\n", progname);
        return 1;
    }

    /* Store utility command */
    utility_argv = argv;
    utility_argc = argc;

    /* Check environment variables */
    ev_trace = (getenv("EV_TRACE") != NULL);
    inotify_workaround = (getenv("ENTR_INOTIFY_WORKAROUND") != NULL);

    const char *restart_sig_env = getenv("ENTR_RESTART_SIGNAL");
    if (restart_sig_env && restart_sig_env[0]) {
        int sig = parse_restart_signal(restart_sig_env);
        if (sig < 0) {
            const char *name = restart_sig_env;
            if (strncmp(name, "SIG", 3) == 0) name += 3;
            fprintf(stderr, "%s: unrecognized signal: %s <> (HUP, INT, QUIT, TERM, USR1, USR2)\n",
                    progname, name);
            return 1;
        }
        restart_signal = sig;
    }

    /* Set up status script if -x is used */
    if (opt_status) {
        if (setup_awk() < 0) {
            return 1;
        }
    }

    /* Read file list from stdin */
    load_files();

    if (ev_trace) {
        /* Get inotify max user watches */
        long open_max = 0;
        FILE *proc_fp = fopen("/proc/sys/fs/inotify/max_user_watches", "r");
        if (proc_fp) {
            if (fscanf(proc_fp, "%ld", &open_max) != 1) open_max = 0;
            fclose(proc_fp);
        }
        if (open_max == 0) {
            open_max = sysconf(_SC_OPEN_MAX);
        }
        fprintf(stderr, "open_max: %ld\n", open_max);
    }

    if (inotify_workaround) {
        fprintf(stderr, "%s: broken inotify workaround enabled\n", progname);
    }

    if (num_watched == 0) {
        fprintf(stderr, "%s: No regular files to watch\n", progname);
        return 1;
    }

    /* Set up inotify */
    ifd = inotify_init1(IN_CLOEXEC | IN_NONBLOCK);
    if (ifd < 0) {
        perror("inotify_init");
        return 1;
    }
    inotify_fd = ifd;

    /* Set up watches */
    setup_watches(ifd);

    /* Set up signals */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigchld;
    sa.sa_flags = SA_RESTART | SA_NOCLDSTOP;
    sigaction(SIGCHLD, &sa, NULL);

    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Ignore SIGPIPE */
    signal(SIGPIPE, SIG_IGN);

    /* Set up TTY if interactive */
    if (!opt_noninteractive) {
        if (open_tty() < 0) {
            return 1;
        }
    }

    /* Set default PAGER if not set */
    if (!getenv("PAGER") || getenv("PAGER")[0] == '\0') {
        setenv("PAGER", "/bin/cat", 1);
    }

    /* Set default trigger path */
    if (num_watched > 0) {
        strncpy(triggered_path, watched[0].path, sizeof(triggered_path) - 1);
        triggered_path[sizeof(triggered_path) - 1] = '\0';
    }

    /* Start awk if status reporting enabled */
    if (opt_status) {
        start_awk();
    }

    /*
     * Initial run:
     * Without -p: run the utility immediately
     * With -p: wait for first event
     */
    if (opt_restart) {
        if (!opt_postpone) {
            /* -r: start persistent process immediately */
            strncpy(trigger_path, triggered_path, sizeof(trigger_path) - 1);
            run_utility(trigger_path);
        }
    } else if (!opt_postpone) {
        /* Run immediately */
        strncpy(trigger_path, triggered_path, sizeof(trigger_path) - 1);
        run_utility(trigger_path);

        /* Wait for child to finish */
        wait_child();

        if (opt_status && awk_pipe) {
            report_status(last_exit_status);
        }

        if (opt_exit) {
            exit_code = get_entr_exit_code(last_exit_status);
            cleanup_awk();
            return exit_code;
        }

        /* Drain any events that arrived during the run */
        drain_inotify_silent(ifd);
    }

    /*
     * Main event loop
     */
    while (!sigint_received) {
        /* Build poll set */
        nfds = 0;

        fds[nfds].fd = ifd;
        fds[nfds].events = POLLIN;
        nfds++;

        if (!opt_noninteractive && tty_fd >= 0) {
            fds[nfds].fd = tty_fd;
            fds[nfds].events = POLLIN;
            nfds++;
        }

        int timeout = -1;

        /* In restart mode, we need to check if child exited */
        if (opt_restart && child_running) {
            timeout = 100;
        }

        int ret = poll(fds, nfds, timeout);

        if (ret < 0) {
            if (errno == EINTR) {
                /* Handle SIGCHLD */
                if (sigchld_received) {
                    sigchld_received = 0;
                    if (check_child_exit()) {
                        if (opt_exit && !opt_restart) {
                            exit_code = get_entr_exit_code(last_exit_status);
                            cleanup_awk();
                            return exit_code;
                        }
                    }
                }
                continue;
            }
            break;
        }

        /* Handle SIGCHLD */
        if (sigchld_received) {
            sigchld_received = 0;
            if (check_child_exit()) {
                if (opt_status && awk_pipe) {
                    report_status(last_exit_status);
                }
                if (opt_exit && !opt_restart) {
                    exit_code = get_entr_exit_code(last_exit_status);
                    cleanup_awk();
                    return exit_code;
                }
            }
        }

        /* Handle poll timeout */
        if (ret == 0) {
            /* Check child status in restart mode */
            if (opt_restart && child_running) {
                if (check_child_exit()) {
                    if (opt_status && awk_pipe) {
                        report_status(last_exit_status);
                    }
                    if (opt_exit) {
                        exit_code = get_entr_exit_code(last_exit_status);
                        cleanup_awk();
                        return exit_code;
                    }
                    /* Restart mode: child exited, wait for event to restart */
                }
            }
            continue;
        }

        /* Handle inotify events */
        if (fds[0].revents & POLLIN) {
            char new_trigger[PATH_MAX_LEN] = "";
            int result = drain_inotify(ifd, new_trigger, sizeof(new_trigger), ev_trace);

            if (result == 2) {
                /* Directory changed - run utility then exit with code 2 */
                if (!child_running) {
                    run_utility(new_trigger[0] ? new_trigger : triggered_path);
                    wait_child();
                    if (opt_status && awk_pipe) {
                        report_status(last_exit_status);
                    }
                }
                fprintf(stderr, "%s: directory altered\n", progname);
                cleanup_awk();
                return 2;
            }

            if (result == 1) {
                if (new_trigger[0]) {
                    strncpy(triggered_path, new_trigger, sizeof(triggered_path) - 1);
                    triggered_path[sizeof(triggered_path) - 1] = '\0';
                }

                if (opt_restart) {
                    /* Kill and restart */
                    kill_child();
                    run_utility(triggered_path);
                } else if (child_running) {
                    /* Child is currently running */
                    if (opt_all) {
                        /*
                         * -a: queue a pending run. When the current child exits,
                         * we'll run again.
                         */
                        pending_run = 1;
                    }
                    /* Without -a: consolidate (ignore this event) */
                } else {
                    /* No child running - start one */
                    run_utility(triggered_path);

                    /* Wait for it to finish */
                    wait_child();

                    if (opt_status && awk_pipe) {
                        report_status(last_exit_status);
                    }

                    if (opt_exit) {
                        exit_code = get_entr_exit_code(last_exit_status);
                        cleanup_awk();
                        return exit_code;
                    }

                    /* Drain events that arrived during child run */
                    if (opt_all) {
                        /* With -a: check if there are pending events and run for each */
                        char pt[PATH_MAX_LEN] = "";
                        while (1) {
                            int r = drain_inotify(ifd, pt, sizeof(pt), ev_trace);
                            if (r <= 0) break;
                            if (r == 2) {
                                fprintf(stderr, "%s: directory altered\n", progname);
                                cleanup_awk();
                                return 2;
                            }
                            if (pt[0]) {
                                strncpy(triggered_path, pt, sizeof(triggered_path) - 1);
                                triggered_path[sizeof(triggered_path) - 1] = '\0';
                                pt[0] = '\0';
                            }
                            /* Run for this pending event */
                            run_utility(triggered_path);
                            wait_child();
                            if (opt_status && awk_pipe) {
                                report_status(last_exit_status);
                            }
                            if (opt_exit) {
                                exit_code = get_entr_exit_code(last_exit_status);
                                cleanup_awk();
                                return exit_code;
                            }
                        }
                    } else {
                        /* Without -a: drain all pending events silently */
                        drain_inotify_silent(ifd);
                    }
                }
            }
        }

        /* Handle child exit in normal mode (non-restart) */
        if (!opt_restart && child_running) {
            if (check_child_exit()) {
                if (opt_status && awk_pipe) {
                    report_status(last_exit_status);
                }
                if (opt_exit) {
                    exit_code = get_entr_exit_code(last_exit_status);
                    cleanup_awk();
                    return exit_code;
                }
                /* If pending run (from -a), execute it */
                if (pending_run) {
                    pending_run = 0;
                    run_utility(triggered_path);
                    /* Don't wait here - let the loop handle it */
                }
            }
        }

        /* Handle TTY input */
        if (!opt_noninteractive && nfds > 1 && (fds[1].revents & POLLIN)) {
            char c;
            ssize_t n = read(tty_fd, &c, 1);
            if (n == 1) {
                if (c == 'q' || c == 3) {  /* 'q' or Ctrl-C */
                    sigint_received = 1;
                    break;
                } else if (c == ' ') {
                    if (opt_restart) {
                        kill_child();
                        run_utility(triggered_path);
                    } else if (!child_running) {
                        run_utility(triggered_path);
                        wait_child();
                        if (opt_status && awk_pipe) {
                            report_status(last_exit_status);
                        }
                        if (opt_exit) {
                            exit_code = get_entr_exit_code(last_exit_status);
                            cleanup_awk();
                            return exit_code;
                        }
                        drain_inotify_silent(ifd);
                    }
                }
            }
        }
    }

    /* Cleanup */
    if (child_running && child_pid > 0) {
        kill(child_pid, SIGTERM);
        waitpid(child_pid, NULL, 0);
    }

    cleanup_awk();

    return 0;
}
