drain_inotify(int ifd, char *out_trigger, int out_size, int ev_trace)
{
    char buf[INOTIFY_BUF_LEN];
    ssize_t len;
    struct inotify_event *event;
    int triggered = 0;
    int dir_changed = 0;

    /* Accumulate fflags per FILE INDEX for ev_trace */
    unsigned int file_fflags[MAX_FILES];
    int file_seen[MAX_FILES];
    memset(file_seen, 0, sizeof(file_seen));
    memset(file_fflags, 0, sizeof(file_fflags));

